button { font-family: "DM Sans", sans-serif; color: var(--ink, #173342); cursor: pointer; touch-action: manipulation; transition: background 0.15s, transform 0.15s; }
button:disabled { cursor: default; }
button:focus-visible { outline: 3px solid #287da2; outline-offset: 4px; }
button:active:not(:disabled) { transform: translateY(2px); }
button svg { width: 22px; height: 22px; }
.ds-primary-btn {
  border: 0;
  border-radius: 9px;
  background: var(--ink, #173342);
  color: var(--cream, #fff6e3);
  padding: 15px 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  font-family: "Barlow Condensed", sans-serif;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.04em;
  min-height: 48px;
}
.ds-primary-btn:hover {
  background: #2e5662;
}
.ds-primary-btn svg {
  width: 20px;
  height: 20px;
}
@media (prefers-reduced-motion: reduce) { button { transition: none; } }

