.ds-launch-btn {
  pointer-events: auto;
  background: var(--ink, #173342);
  color: var(--cream, #fff6e3);
  border: 0;
  border-radius: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px 20px;
  min-height: 62px;
  box-shadow: 0 5px 12px #5e462b24;
  text-align: left;
}
.ds-launch-btn > svg {
  width: 29px;
  height: 29px;
  stroke: #f1b176;
}
.ds-launch-btn strong {
  display: block;
  font-size: 22px;
  letter-spacing: 0.03em;
  line-height: 1;
}
.ds-launch-btn small {
  display: block;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  margin-top: 6px;
  color: #bed1cb;
}
.ds-launch-btn:hover:not(:disabled) {
  background: #2b5360;
}
.ds-launch-btn:disabled {
  background: #5f726d;
  box-shadow: none;
}
.ds-launch-btn:disabled small {
  color: #fff1d3;
}
@media (prefers-reduced-motion: reduce) { button { transition: none; } }
.ds-launch-btn strong { font-family: "Barlow Condensed", sans-serif; } @media (pointer: coarse) { .ds-launch-btn { min-height: 68px; } }

.ds-orbit-panel {
  display: flex;
  gap: 11px;
  align-items: center;
  background: var(--cream, #fff6e3);
  border-radius: 12px;
  padding: 12px 16px 12px 12px;
  box-shadow: 0 5px 12px #5e462b24;
}
.ds-orbit-icon {
  width: 38px;
  height: 38px;
  border-radius: 9px;
  background: #d9e9dc;
  display: grid;
  place-items: center;
}
.ds-orbit-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--teal, #3c9298);
  stroke-width: 2.5;
}
.ds-orbit-caption {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: baseline;
  margin-bottom: 8px;
}
.ds-orbit-caption strong {
  font-size: 16px;
  letter-spacing: 0.04em;
}
.ds-orbit-caption span {
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.ds-scrap-pips {
  display: flex;
  gap: 4px;
}
.ds-scrap-pips i {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  background: #d8d2bc;
}
.ds-scrap-pips i.ds-filled {
  background: #3b8991;
}
@media (prefers-reduced-motion: reduce) { button { transition: none; } }
.ds-orbit-panel { color: var(--ink, #173342); font-family: "DM Sans", sans-serif; } .ds-orbit-caption strong { font-family: "Barlow Condensed", sans-serif; }

