.ds-modal-card {
  background: var(--cream, #fff6e3);
  border-radius: 18px;
  padding: 32px 38px;
  max-width: 490px;
  width: 100%;
  box-shadow: 0 12px 36px #1d262938;
  max-height: 100%;
  overflow: auto;
  text-align: center;
  scrollbar-color: #9da88d #fff6e3;
}
.ds-modal-card h2 {
  font-size: 45px;
  font-weight: 800;
  line-height: 1;
  margin: 15px 0;
}
.ds-modal-card > p {
  font-size: 13px;
  line-height: 1.7;
  color: #4c625c;
  margin: 0 0 24px;
}
.ds-modal-card dl {
  text-align: left;
  font-size: 12px;
  line-height: 1.6;
  margin: 0 0 24px;
}
.ds-modal-card dl > div {
  display: grid;
  grid-template-columns: 60px 1fr;
  gap: 12px;
  padding: 10px 0;
  border-top: 1px solid #dbd1bc;
}
.ds-modal-card dt {
  font-weight: 700;
}
.ds-modal-card dd {
  margin: 0;
  color: #52665d;
}
@media (prefers-reduced-motion: reduce) { button { transition: none; } }
.ds-modal-card { color: var(--ink, #173342); font-family: "DM Sans", sans-serif; } .ds-modal-card h2 { font-family: "Barlow Condensed", sans-serif; }

.ds-ability-chip {
  display: flex;
  align-items: center;
  gap: 4px;
  background: #fff6e3ed;
  color: var(--ink, #173342);
  border-radius: 6px;
  padding: 5px 6px;
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}
.ds-ability-chip svg {
  width: 18px;
  height: 18px;
  color: #2d7177;
} .ds-ability-chip {font-family: "DM Sans", sans-serif;}

.ds-upgrade-choice {
  position: relative;
  display: flex;
  flex-direction: column;
