  padding: 20px;
  text-align: left;
}
.ds-upgrade-choice:hover {
  background: #e4d7b8;
}
.ds-upgrade-icon {
  display: grid;
  place-items: center;
  width: 45px;
  height: 45px;
  border-radius: 9px;
  background: #f4c44b;
  color: #173342;
  flex: 0 0 auto;
}
.ds-upgrade-icon svg {
  width: 29px;
  height: 29px;
}
.ds-upgrade-text {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.ds-upgrade-rank {
  font-size: 9px;
