  color: #35645e;
}
.ds-upgrade-text strong {
  font-size: 27px;
  line-height: 1;
}
.ds-upgrade-description {
  font-size: 12px;
  line-height: 1.55;
}
.ds-upgrade-choice kbd {
  position: absolute;
